int logfmt_append(char *buf, size_t buf_sz, const char *key, const char *val) {
    if (buf[0] != '\0') {
        // Find the end of the current content
        const char *end = strchr(buf, '\0');
        while (end > buf && isspace((unsigned char)*(end - 1))) {
            --end;
        }
        if (end > buf && *(end - 1) != '=') {
            size_t len = end - buf;
            if (len + 3 + strlen(key) + strlen(val) + 1 >= buf_sz) return -1; // +3 for ' ', '=', and null terminator
            *end++ = ' ';
        }
    }
    return _write_pair(buf, buf_sz, key, val);
}

