int logfmt_parse_multi(const char *in, char **keys, char **vals, size_t max_pairs) {
    const char *pair = in;
    size_t count = 0;

    while (pair && *pair && count < max_pairs) {
        const char *eq = strchr(pair, '=');
        if (!eq) break;

        size_t klen = (size_t)(eq - pair);
        keys[count] = malloc(klen + 1);
        if (!keys[count]) return -1;
        strncpy(keys[count], pair, klen);
        keys[count][klen] = '\0';

        const char *val_start = eq + 1;
        while (*val_start == ' ') val_start++; // Skip leading spaces

        if (*val_start == '"') {
            const char *quote_end = strchr(val_start + 1, '"');
            if (!quote_end) {
                free(keys[count]);
                return -1; // No closing quote
            }
            size_t vlen = (size_t)(quote_end - val_start - 1);
            vals[count] = malloc(vlen + 1);
            if (!vals[count]) {
                free(keys[count]);
                return -1;
            }
            strncpy(vals[count], val_start + 1, vlen);
            vals[count][vlen] = '\0';
        } else {
            const char *end = strpbrk(val_start, "= ");
            if (!end) end = val_start + strlen(val_start);
            size_t vlen = (size_t)(end - val_start);
            vals[count] = malloc(vlen + 1);
            if (!vals[count]) {
                free(keys[count]);
                return -1;
            }
            strncpy(vals[count], val_start, vlen);
            vals[count][vlen] = '\0';
        }

        pair = end ? end + 1 : NULL;
        count++;
    }

    return count;
}

